TLM.f("Tempora/Pent13-2",{"officium":"Feria Tertia infra Hebdomadam XIII post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent13-0","from":{"Introitus":"Tempora/Pent13-0","Oratio":"Tempora/Pent13-0","Lectio":"Tempora/Pent13-0","Graduale":"Tempora/Pent13-0","Evangelium":"Tempora/Pent13-0","Offertorium":"Tempora/Pent13-0","Secreta":"Tempora/Pent13-0","Communio":"Tempora/Pent13-0","Postcommunio":"Tempora/Pent13-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 73:20; 73:19; 73:23"},{"k":"text","la":"Réspice, Dómine, in testaméntum tuum, et ánimas páuperum tuórum ne derelínquas in finem: exsúrge, Dómine, et júdica causam tuam, et ne obliviscáris voces quæréntium te."},{"k":"ref","la":"Ps 73:1"},{"k":"text","la":"Ut quid, Deus, reppulísti in finem: irátus est furor tuus super oves páscuæ tuæ?"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Réspice, Dómine, in testaméntum tuum, et ánimas páuperum tuórum ne derelínquas in finem: exsúrge, Dómine, et júdica causam tuam, et ne obliviscáris voces quæréntium te."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, da nobis fídei, spei et caritátis augméntum: et, ut mereámur asséqui quod promíttis, fac nos amáre quod prǽcipis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Gálatas"},{"k":"ref","la":"Gal 3:16-22"},{"k":"text","la":"Fratres: Abrahæ dictæ sunt promissiónes, et sémini ejus. Non dicit: Et semínibus, quasi in multis; sed quasi in uno: Et sémini tuo, qui est Christus. Hoc autem dico: testaméntum confirmátum a Deo, quæ post quadringéntos et trigínta annos facta est lex, non írritum facit ad evacuándam promissiónem. Nam si ex lege heréditas, jam non ex promissióne. Abrahæ autem per repromissiónem donávit Deus. Quid igitur lex? Propter transgressiónes pósita est, donec veníret semen, cui promíserat, ordináta per Angelos in manu mediatóris. Mediátor autem uníus non est: Deus autem unus est. Lex ergo advérsus promíssa Dei? Absit. Si enim data esset lex, quæ posset vivificáre, vere ex lege esset justítia. Sed conclúsit Scriptúra ómnia sub peccáto, ut promíssio ex fide Jesu Christi darétur credéntibus."}],"Graduale":[{"k":"ref","la":"Ps 73:20; 73:19; 73:22"},{"k":"text","la":"Réspice, Dómine, in testaméntum tuum: et ánimas páuperum tuórum ne obliviscáris in finem."},{"k":"text","la":"Exsúrge, Dómine, et júdica causam tuam: memor esto oppróbrii servórum tuórum. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 89:1"},{"k":"text","la":"Dómine, refúgium factus es nobis a generatióne et progénie. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 17:11-19"},{"k":"text","la":"In illo témpore: Dum iret Jesus in Jerúsalem, transíbat per médiam Samaríam et Galilǽam. Et cum ingrederétur quoddam castéllum, occurrérunt ei decem viri leprósi, qui stetérunt a longe; et levavérunt vocem dicéntes: Jesu præcéptor, miserére nostri. Quos ut vidit, dixit: Ite, osténdite vos sacerdótibus. Et factum est, dum irent, mundáti sunt. Unus autem ex illis, ut vidit quia mundátus est, regréssus est, cum magna voce magníficans Deum, et cecidit in fáciem ante pedes ejus, grátias agens: et hic erat Samaritánus. Respóndens autem Jesus, dixit: Nonne decem mundáti sunt? et novem ubi sunt? Non est invéntus, qui redíret et daret glóriam Deo, nisi hic alienígena. Et ait illi: Surge, vade; quia fides tua te salvum fecit."}],"Offertorium":[{"k":"ref","la":"Ps 30:15-16"},{"k":"text","la":"In te sperávi, Dómine; dixi: Tu es Deus meus, in mánibus tuis témpora mea."}],"Secreta":[{"k":"text","la":"Propitiáre, Dómine, pópulo tuo, propitiáre munéribus: ut, hac oblatióne placátus, et indulgéntiam nobis tríbuas et postuláta concedas."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 16:20"},{"k":"text","la":"Panem de cœlo dedísti nobis, Dómine, habéntem omne delectaméntum et omnem sapórem suavitátis."}],"Postcommunio":[{"k":"text","la":"Sumptis, Dómine, cœléstibus sacraméntis: ad redemptiónis ætérnæ, quǽsumus, proficiámus augméntum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"f03985903daa2a5d":{"t":"Ps 73, 20, 19 i 23, Ps 73, 1\n(Ps 73, 20, 19 i 23) Pogledaj, Gospodine, na svoj zavjet i duše siromaha svojih ne zaboravi dokraja. Ustani, Gospodine, brani stvar svoju, ne ogluši se na glasove onih koji te traže. (Ps 73, 1) Zašto si nas, Bože, odbacio za vazda? Zašto se raspalio tvoj gnjev na ovce paše tvoje?\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 73, 20, 19 i 23) Pogledaj, Gospodine, na svoj zavjet i duše siromaha svojih ne zaboravi dokraja. Ustani, Gospodine, brani stvar svoju, ne ogluši se na glasove onih koji te traže."},"f924a6de3ba45f4c":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, daj da nam poraste vjera, ufanje i ljubav, te učini da ljubimo što zapovijedaš, da bismo postigli što obećavaš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e18934ddbe6dec3a":{"t":"Gal 3, 16-22\nČitanje Poslanice bl. Pavla apostola Galaćanima. Braćo, Abrahamu i njegovu potomku bila su zadana obećanja. Ne kaže: i potomcima kao mnogima, nego kao jednome: I tvojem potomku, koji je Krist. A kažem ovo: Zakon koji je nastao poslije četiri stotine i trideset godina ne ukida zavjeta koji je potvrđen od Boga, da bi tako poništio obećanje. Ako je nasljedstvo po zakonu, onda nije po obećanju, a Bog je Abrahamu dao po obećanju. – Čemu dakle zakon? Zakon, objavljen od anđela preko posrednika, dan je da se jače vide prestupci dok ne dođe potomak za kojega su dana obećanja. Posrednika nema, ako postoji samo jedna strana, a Bog je jedan. Je li dakle zakon protivan Božjim obećanjima? Nipošto. Doista, da je dan zakon koji bi mogao davati život, pravda bi ovisila o zakonu. Ali prema Pismu sve je podložno grijehu, da se vjernicima obećanje ostvari po vjeri u Isusa Krista."},"278fa3e553d7e605":{"t":"Ps 73, 20 i 19 i 22\nPogledaj, Gospodine, na svoj zavjet i duše siromaha svojih ne zaboravi dokraja. Ustani, Gospodine, brani stvar svoju, spomeni se sramote slugu svojih.\n\nPs 89, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nBože, ti si nam bio utočište od koljena do koljena. <i>Aleluja</i>."},"c12bbf19a77e625c":{"t":"Lk 17, 11-19\nSlijedi sveto Evanđelje po Luki. U ono vrijeme idući Isus prema Jeruzalemu prolazio je između Samarije i Galileje. Kad je ulazio u neko selo, dočeka ga deset gubavaca. Oni su stajali podalje i vapili: Isuse, učitelju, smiluj se nama! Isus ih opazi i reče im: Idite, pokažite se svećenicima. I dok su išli, očiste se od gube. Tada jedan od njih, čim vidje da je ozdravio, vrati se glasno slaveći Boga i padne ničice pred njega i zahvali mu. I taj je bio Samaritanac. Tada Isus upita: Zar ih se nije očistilo deset? Gdje je ostalih devet? Nitko se ne vrati, da poda slavu Bogu, osim ovog tuđinca! Onda mu reče: Ustani, idi, tvoja te je vjera spasila.","v":"et → ∅"},"23887187251b9760":{"t":"Ps 30, 15-16\nJa se uzdam u tebe, Gospodine! Govorim: Ti si Bog moj, u tvojim je rukama sudbina moja."},"85702ff26e4d340b":{"t":"Budi, Gospodine, milostiv svome narodu, pogledaj milostivo ove darove i primi ih kao pomirbeni dar te nam daj oproštenje i udijeli što molimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"16807625d475b4fe":{"t":"Mudr 16, 20\nKruh s neba dao si nam, Gospodine, koji u sebi ima svaku slast i svu ugodnost."},"e925bfac9b30685f":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da po primljenim nebeskim otajstvima sve više napredujemo k vječnom otkupljenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
